window.POETRY_REGISTER("v5-extra-11-5-0-f1769f1ad0ee.js",{"poems":[[9858,2],[19859,2],[22501,2],[23555,2],[23602,2],[30059,2],[51933,2],[51939,2],[52299,2],[52360,2],[52842,2],[53144,2],[53601,2],[53741,2],[54392,2],[54559,2],[54587,2],[55214,2],[55259,2],[55461,2],[55813,2],[55834,2],[55881,2],[56861,2],[56878,2],[57322,2],[58338,2],[96445,7],[113121,7],[118582,7],[121634,7],[126785,7],[129972,7],[132304,7],[136929,7],[138019,7],[143355,7],[150898,7],[192130,7],[193851,7],[194740,7],[221354,7],[224381,7],[225121,7],[229206,7],[234159,7],[250736,7],[259632,7],[261525,7],[262739,7],[269876,7],[272021,7],[272114,7],[272147,7],[284213,7],[288139,7],[288948,7],[304337,7],[310413,7],[313562,7],[316512,7],[322786,7],[331116,7],[337800,9],[339653,9],[340214,9],[342620,9],[343205,9],[347190,9],[347210,9],[350997,9],[351001,9],[353572,9],[356906,9],[365648,9],[368358,10],[369790,10],[369960,10],[370251,10],[371067,10],[371145,10],[373002,10],[375221,10],[376591,10],[376600,10],[378268,10],[379694,10],[381813,0],[381887,0],[391461,13],[393528,13],[403596,8],[405137,8],[409736,8],[412367,8],[413226,8],[415442,8],[417595,8],[433113,8],[433267,8],[435061,8],[436465,8],[436467,8],[436499,8],[436697,8],[446650,8],[451334,8],[453880,8],[458316,8],[459575,8],[467673,8],[467824,8],[471300,8],[471429,8],[473640,8],[473648,8],[473657,8],[502478,8],[502482,8],[504337,8],[509624,8],[525464,8],[528386,8],[552121,8],[554950,8],[556446,8],[564128,8],[575420,8],[575422,8],[581832,8],[589108,8],[596184,8],[608049,8],[608132,8],[625634,8],[625635,8],[627359,8],[648431,16],[649034,5],[652762,5],[657023,5],[658714,5],[660088,5],[660484,5],[660776,5],[661130,5],[661228,5],[662756,5],[664115,5],[664502,5],[668900,5],[671199,5],[674389,5],[680916,5],[681509,5],[686297,5],[691393,5],[693296,5],[697153,5],[701792,5],[703589,5],[706926,5],[706948,5],[711192,5],[711443,5],[711895,5],[720890,5],[725604,5],[725696,5],[735261,5],[739629,20]],"pairs":[["我思仙人乃在碧海之东隅","海寒多天风",0],["卜师烧锥钻灼满板如星罗","此外内外官",1],["驾车六九五十四头蛟螭虬","掣电九火辀",2],["千年万岁父子不敢相灭亡","殁后千余载",3],["高兮漫兮吾孰知天否与灵","取人之仰者",4],["尧舜禹汤文武周孔皆为灰","酌此一杯酒",5],["就是节取使用她的校记的","己本拟作疑",6],["但李字与昔音形均无关系","似只可存疑",7],["宜为道州南海所宝也云云","今细读斯记",8],["未有如此篇之意远而美者","因题以永之",9],["武后至肃宗间仅六七十年","不至隔五世",10],["仆仅见宣和所收许浑诗稿","精致亦如之",11],["凡得铭志歌诗等八百五篇","辑为二十卷",12],["戒贤伽蓝西南行四五十里","渡尼连禅河",13],["又前首五六句我逐江潭雁","君随海上鸥",14],["误将苗发职衔与诗题相连","遂误成端诗",15],["其子杨椿省试得九十六名","殿试魁天下",16],["且在大和二年后三十余祀","纪年亦不合",17],["似与白氏所闻者最为接近","故录为正文",18],["观察使林衮同业儒同入关","至扬子渡口",19],["干宁四年季夏二十九日书","珂另有赞语",20],["于岩下嵌空处见题诗一首","虽苔藓昏蚀",21],["诸诗皆新罗人在唐时所作","因未注出处",22],["知二人诗在宋时已有传误","但应以孰是",23],["江南李后主尝一日幸后湖","开宴赏荷花",24],["廖齐父爽直尝为永州刺史","齐后游零陵",25],["竹皮弓纸间密贮龙麝末香","每宫嫔群聚",26],["鹤飞玉山千仞直上青松巢","索然两衰翁",27],["小者老祠佛庙往往龛屋壁","忆初来长安",28],["风回地近兮将亦闻乎犬鸡","信有居者兮",29],["褐冠释氏胡为笑傲于其中","我将学彼术",30],["夫子乃以侯嬴所为疑三子","王泽既未竭",31],["砚中安得有星点点明如金","既非瑕掩瑜",32],["但置寒窗笔札往古研于今","大刚无睢睢",32],["旦暮之间辄变喜爱成嫌猜","介之不恤我",33],["天寥寥兮河汉风浪西南倾","山川悠远兮",34],["中有晶荧照耀金碧之楼台","钱塘未应邈",35],["但愿寄身江上一叶之秋莲","万物才不才",36],["有时露出佛祖莫穷底机关","于一毫端中",37],["公有瑊玏玄厉兮磨而不磷","栋梁兮媞媞",38],["神仙窟宅合在东南北西陬","周游几千里",39],["上自皮羽之服下至垂衣裳","盘古众支派",40],["彼湘之人士兮咏游而鱼鱼","长者兮矩步",41],["又见韩愈孟郊恨不如云龙","我今与子别",42],["二百四十有二年兮褒与诛","目目自有条",43],["子又乌知书非云而云非书","以此寿子身",43],["邦之人兮建德之游春台嬉","坡仙昔颍尾",44],["林密林疎兮溪山自为秋春","不见兮相思",45],["下有藤蔓老树根据枝相虬","想其结缔初",46],["谁知公心兮不独桂人是忧","蘅杜兮荐羞",47],["云仍诜诜褒衣博带千官班","向来山泽癯",48],["亲戚朋旧相见朝夕无缘由","尔鼇若未动",49],["胡不铲尽白险直使平如洲","使家河源来",50],["下至旄头式候亦羿万之伍","则唐虞之隆",51],["而犹拳拳于富贵功名之竞","其言虽独应",52],["因送客而遂及阳关之旧知","盖拊髀之思",53],["叹息不知铸自三代之何年","邀翁问所得",54],["岂惟岁律兮嗟世道之益穷","有美君子兮",55],["当时一段议论千古生清风","美妇未必美",56],["历代祖师远之如龙怖金翅","唯有活衲僧",57],["不尔鳏翁嫠妇对花成咨嗟","秋夜楼上月",58],["登山须登万丈嵩华之乔岳","高高高无极",59],["顷刻鵞溪幻出白练之寒江","碧玉之奇峰",60],["空有金莲宝炬错落悬珠楹","杨柳兮青青",61],["千古万古洗濯下土愚民愚","男子学麟凤",62],["空教我停霜毫半晌无才思","往常得兴时",63],["自古富贵埋没野草空累累","我欲酹北斗",64],["心脾一片常若冰雪之洒然","瞳子点漆黑",65],["至于题品人物犹作泾水浑","入城市井喧",66],["倒泻银河千丈玉乳溅飞花","寄语陆鸿渐",67],["应有山灵夜护林壑动龙蛇","秉烛下山去",67],["振鬣仰吁物固各有所遇兮","遇固各有时",68],["徒使襄王朝朝暮暮行雨处","君家西江西",69],["与沈世契如水有委则有源","新至切母脉",70],["说也孝感可以假上帝通神","明是谓同姓",70],["划如雌龙挟雨归吟百丈湫","纬嫠与爨妇",71],["我行终日仰羡木杪幽禽啼","但见雨色来",72],["岂有江山如此不著幽人栖","颇闻山中人",72],["飞龙捷鬼凿开混沌巢神仙","道逢四五叟",73],["得不俯慑崭岩箐栈无穷渊","嗟兹大凡夫",73],["文成五利受宠骤贵祈长年","仙人自有真",73],["一对虎猫儿绣凳上相偎定","觑了动人情",74],["其肯贪天之禄一日离其亲","年未及致事",75],["巢父闻之犹为洗耳河之湄","奈何葛仙翁",76],["上有危峰横空插汉高巉岩","沧海深莫测",77],["谁探千载太史禹穴之遗书","兴因东归发",77],["佯狂落魄酒浇舌本黄河干","我有孤竹笛",78],["惟有两鬼两眼昼夜长相追","有物来掩犯",79],["老胡不识轻重长短多与寡","但觉饥则食",80],["何如老胡终日瞑坐山之隈","五伯与七国",80],["顿觉胸次洗空世虑尘梦醒","弹琴坐盘石",81],["盖若市门使我掩面不得藏","昨日县令媒",82],["安得与尔遁还天地终无端","东望扶桑枝",83],["嗟彼吴盐蜀锦那得利吾财","利亦不足美",84],["一龙搅海奋迅直上青天衢","雄者筋脉紧",85],["结庐其侧相与放旷而逍遥","园绮非陋汉",86],["又恐受赇枉法为奸触大罪","身死而家灭",87],["廉吏而可为者当时有清名","而不可为者",88],["不尔鳏翁嫠妇对花成咨嗟","秋夜楼上月",89],["空有金莲宝炬错落悬珠楹","杨柳兮青青",90],["始知天地之胜唯有兹山钟","我昔探禹穴",91],["歌风之碑烟霜磨灭不可读","遥望芒石易",92],["展图不觉再把短发临风搔","忆当天宝年",93],["何用呼吸百里昼夜东西旋","大阍笑绝倒",94],["惟究心乎羲文周孔之遗经","一旦起作郡",95],["旁驰余子犹以清渭临浊泾","太史犹巨钟",95],["坐待真主应运九五开乾坤","鹤书自天来",96],["东南倭乱韶光都过乱离中","登眺觉心慵",97],["子路负米遥遥百里不敢难","拳拳奉颜色",98],["麻姑书遥海上孤月寒潮带","归鱼天空百",99],["惟有秋霜烈日皎皎是孤忠","曾攀丹桂枝",100],["挂在清溪石上万古之松傍","洪君求我歌",101],["或如黄河半解不解之冰澌","或如白凤尾",102],["遍观寿山寺外崒嵂之奇峰","天风吹我衣",103],["直欲播颂焉得巨笔如长椽","区区韦布士",104],["及有四时可饮不竭之清泉","欲进须鱼贯",105],["太行恒华不得并列将如何","我山不在大",106],["徘徊把杯思欲丹青写之人","则无城中郭",107],["上有悬崖石栈百折而造天","嵚崟兮巉岩",108],["祥虹瑞霭往往早暮相鲜新","箕山将让许",109],["何者一翁素发渥颜而飘须","解衣赠龙子",110],["乃是翁家郁林太守之所怀","聊采仙君名",111],["又疑泰华衡庐飞过剑门来","白云几朝莫",112],["直须名王授首霜刃赭花斑","冲风单于庭",113],["命词臣濂草檄谕彼中华民","长驱入河洛",114],["一双羽翮云中合沓而飞翔","合沓而飞翔",115],["但见一双鲤鱼遥堕青云端","呼童剖此鲤",116],["彼国之王所与游者何人兮","华胥之君臣",117],["焚香告天愿天为我开咽喉","颜渊鲁高士",118],["我巳见其映雪千树之玉津","漂渺一眉金",119],["又时立仗食三品料饱肚肠","一马服盐车",120],["而使其涕之不涔淫而滂沱","悠悠兮终古",121],["云是分别在朝在野之贤豪","吾犹一计吏",122],["高复低兮日之方中能几时","听我高低吟",123],["枉我终日来来往往江之湄","人笑也不知",124],["如王屋太行之一在朔之东","一在雍之南",125],["高阳徒侣当年亦复气锵锵","更有庐山谷",126],["何以不与禽兽草木为等伦","一心运万化",127],["故立此论可与日月同光新","为君不知此",127],["又为迎至龟岩之下养且耕","儿壮母发白",128],["谁言自古隔绝不与通中原","忆我总角年",129],["但见洪涛巨浪从我今谁由","何当挟飞仙",130],["云是蘧仙手植距今三千年","内注沆瀣华",131],["何不去而海上从彼辟谷仙","骑当飞兔马",132],["吁嗟马乎古今识者凡几徒","前有九方圣",133],["命词臣濂草檄谕彼中华民","长驱入河洛",134],["一双羽翮云中合沓而飞翔","合沓而飞翔",135],["但见一双鲤鱼遥堕青云端","呼童剖此鲤",135],["焚香告天愿天为我开咽喉","颜渊鲁高士",136],["然不得欢乐兮当我之盛年","怨兮欲问天",137],["却真珠厂玉漏恩甚兮忽绝","守礼兮多尤",138],["大扣小扣泛尔肆应无纤遗","台鼎赞谟略",139],["豫章西山云堂院中亦何有","我欲赚汝去",140],["砉尔崩涛灭顶瞀若瞽与聋","颠倒下上间",141],["那许太华恒霍嵩高与之并","上有中和壑",142],["何来高第弟子入室还操戈","逆阉固无论",143],["不知空厨之下久已无炊烟","女头无媚骨",144],["那能气吞齐鲁直溯鸿蒙初","宵来梦羽人",145],["或如湘流帆转九折波沄沄","纤浓各意态",146],["浅深乃有六十余种相争妍","不暇细分别",147],["乃见百川清浊纡疾之不同","八方殊风雨",148],["庶与朱陵洞天岣嵝铭相方","惜哉天宝末",149],["不知仙人游戏蓬莱复何状","莫生世外心",150],["但觉山空树古天容青江生","是时大快意",151],["坐令日月惨黩天地为悲愁","我欲请王母",152],["长白山上有石虎立而参天","下为松花江",153],["九头之纪重纪天地人三皇","北不尽幽燕",154],["乃与龙伯大人之国相颉颃","天欲无三光",154],["只是依人憔悴青鬓损朱颜","传语曲江头",155],["却似天孙几望断新秋初七","正闲看北斗",156],["我欲更向成都为君一问卜","如谓文无灵",157],["但见天光水色一气摩硠硠","大嶝路最近",158],["瑶台上步秋影绡衣归来好","叹鹫岭尖风",159],["汝家乃在沧溟之西见日没","日出必有方",160],["仍愿丸泥封关再闭一千载","天雨新好花",161],["君实有弟不获传国如金瓯","君亦有国民",162],["伏念国亡君死实惟仇人由","当时天使来",162],["又若诸天游戏随意浮青莲","青莲不可采",163],["儿恨一十八年光阴箭去弩","人绘先生事",164],["又如湘灵鼓瑟弦柱声呜咽","左携浮邱袖",165],["蜀山千点参差罗列儿孙俦","花为优昙色",166],["惟有朝暾荡漾倒挂金芙蓉","眷此灵异境",166],["串铃摇荡先令宽处避侧边","一盘复一盘",167],["微风拂拂恍惚相引来天阊","乱山束车路",168],["贞观事业犹于千载想见之","驱车下山去",168],["乃见百川清浊纡疾之不同","八方殊风雨",169],["何异越人章甫逐臭之都梁","苟不覆酱瓿",170],["惜也不为世用而令人悲伤","嗟予与汝兮",170]]});
